<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { Check, Plus, Sparkles } from 'lucide-vue-next'
import { job } from '../api'
import StatusChip from '../components/StatusChip.vue'
import { groups, state, toggle } from '../state'
interface Candidate { id: string; unit: string; department: string; major_name: string; major_code: string; group: string; preference_score: number; related_rules: { year: number; scope: string; statements: string[] }[]; background: { friendliness: string; note: string } }
interface Result { ranking: Candidate[]; eligible_candidates: number; basis: string; friendliness_policy: string; data_version: string }
const majors = ref(['计算机', '软件', '人工智能', '网安']); const weights = reactive<Record<string, number>>({})
const majorWeight = ref(7); const groupWeight = ref(3); const background = ref('all'); const mode = ref('全日制')
const result = ref<Result | null>(null); const busy = ref(false); const message = ref(''); let revision = 0
watch(groups, () => groups.value.forEach(group => { weights[group] ??= 5 }), { immediate: true })
const signature = computed(() => JSON.stringify([majors.value, weights, majorWeight.value, groupWeight.value, background.value, mode.value, state.version]))
watch(signature, () => { revision++; result.value = null; message.value = '' })
async function recommend() {
  if (!majors.value.length || !(majorWeight.value + groupWeight.value > 0)) { message.value = '请至少选择一个专业，并让一项权重大于零。'; return }
  if (!state.version) { message.value = '资料版本尚未就绪，请刷新数据。'; return }
  const submitted = revision; busy.value = true; message.value = '正在按你的偏好筛选…'
  try {
    const value = await job<Result>('/recommendations', { data_version: state.version, majors: majors.value, group_weights: { ...weights }, major_weight: majorWeight.value, group_weight: groupWeight.value, background_filter: background.value, mode: mode.value, limit: 30 })
    if (submitted !== revision) { message.value = '条件已改变，填写内容保留，请重新推荐。'; return }
    result.value = value; message.value = `找到 ${value.eligible_candidates} 个候选，展示前 ${value.ranking.length} 个。`
  } catch (e) { message.value = e instanceof Error ? e.message : '推荐暂不可用。' } finally { busy.value = false }
}
</script>
<template><section class="card recommendation-form"><div class="card-heading"><div><span class="eyebrow">YOUR PREFERENCES</span><h2>你更看重什么？</h2><p>不需要填写初试成绩，先看专业和院校类别。</p></div><span class="accent-icon"><Sparkles :size="23" /></span></div><form @submit.prevent="recommend"><div class="form-section"><label class="form-label">感兴趣的专业</label><div class="choice-pills"><label v-for="major in ['计算机', '软件', '人工智能', '网安']" :key="major" :class="{ selected: majors.includes(major) }"><input v-model="majors" type="checkbox" :value="major"><Check v-if="majors.includes(major)" :size="14" />{{ major === '软件' ? '软件工程' : major === '网安' ? '网络安全' : major }}</label></div></div><div class="preference-grid"><div class="form-section"><label class="form-label">专业匹配权重 <b>{{ majorWeight }}</b></label><input v-model.number="majorWeight" type="range" min="0" max="10" aria-label="专业匹配权重"></div><div class="form-section"><label class="form-label">院校类别权重 <b>{{ groupWeight }}</b></label><input v-model.number="groupWeight" type="range" min="0" max="10" aria-label="院校类别权重"></div></div><div class="form-section"><label class="form-label">院校类别偏好</label><p class="muted">这些是资料分组，不是实力榜。每类初始同为 5 分，你来决定偏好。</p><div class="group-preferences"><label v-for="group in groups" :key="group"><span>{{ group }}</span><input v-model.number="weights[group]" type="range" min="0" max="10" :aria-label="`${group}类别偏好`"><b>{{ weights[group] }}</b></label></div></div><div class="preference-grid"><label>本科背景相关资料<select v-model="background"><option value="all">全部；未知保持待核</option><option value="related-rules">已有相关报考规则</option><option value="unknown">友好程度尚未核准</option></select></label><label>学习方式<select v-model="mode"><option>全日制</option><option>非全日制</option><option value="all">全部方式</option></select></label></div><div class="form-actions"><button class="button" :disabled="busy" type="submit"><Sparkles :size="16" />{{ busy ? '正在筛选' : '发现候选专业' }}</button><span role="status" class="muted">{{ message }}</span></div></form></section><div class="method-note"><strong>关于双非友好</strong><p>未发现限制、同等学力规则或单篇经验帖，都不足以认定“双非友好”。当前没有核准的正向证据，保持待核，不计入偏好分。</p></div><div v-if="result" class="programme-grid"><article v-for="(candidate, index) in result.ranking" :key="candidate.id" class="card recommendation-card"><div class="card-heading"><span class="rank-number">{{ String(index + 1).padStart(2, '0') }}</span><span class="preference-score">{{ candidate.preference_score.toFixed(1) }}<small>偏好分 / 10</small></span></div><h3>{{ candidate.unit }}</h3><p>{{ candidate.major_name }} <span class="code-label">{{ candidate.major_code }}</span></p><p class="muted">{{ candidate.department }}</p><div class="candidate-tags"><span class="mini-pill">{{ candidate.group }}</span><StatusChip text="本科背景待核" /></div><details v-if="candidate.related_rules.length" class="related-rules"><summary>相关报考规则</summary><div v-for="rule in candidate.related_rules" :key="rule.scope + rule.year"><strong>{{ rule.year }} · {{ rule.scope }}</strong><p v-for="statement in rule.statements" :key="statement">{{ statement }}</p></div></details><button class="button subtle full-width" @click="toggle(candidate.id)"><Check v-if="state.selected.includes(candidate.id)" :size="15" /><Plus v-else :size="15" />{{ state.selected.includes(candidate.id) ? '已加入比较' : '加入比较清单' }}</button></article><div v-if="!result.ranking.length" class="empty-state"><h3>暂未找到匹配候选</h3><p>试试调整专业或报考规则条件。</p></div></div><p v-if="result" class="muted result-policy">{{ result.basis }}</p></template>
